/** ローカルの once-guard: 並行二重ロードを防ぐ */
let _taLoaded = false;
let _mfLoaded = false;

/** 現在アクティブなレンズ */
let _lens = 'total';

/**
 * プロキシ ETF の短縮表示名（誤読防止・#529）。アクティブ投信は本体PERが取れず代替指数ETFの
 * 実績PERを表示しているため、どの指数かをバッジに明記する。キー＝保有の `ySymbol`（実際に
 * PER を引いた proxy 銘柄）。未登録は position の proxyName / ySymbol にフォールバック。
 * @type {Record<string,string>}
 */
const PROXY_LABELS = {
  '1306.T': 'TOPIX',
  '2516.T': 'グロース250',
  '1477.T': '小型株(1477)',
  ACWI: 'ACWI',
  SHV: '米短期債',
};

/**
 * データを必要なら読み込む（既ロード済みならスキップ）。
 * @returns {Promise<void>}
 */
async function _ensureData() {
  const loads = [];
  if (!_taLoaded) {
    loads.push(
      loadTargetAllocation().then(() => {
        _taLoaded = true;
      })
    );
  }
  if (!_mfLoaded) {
    loads.push(
      loadMfHoldings().then(() => {
        _mfLoaded = true;
      })
    );
  }
  if (!valuationsLoaded()) {
    loads.push(loadValuations());
  }
  if (!triggersLoaded()) {
    loads.push(loadTriggers());
  }
  if (!outcomesLoaded()) {
    loads.push(loadVerdictOutcomes());
  }
  await Promise.all(loads);
}

/**
 * 数値を小数点1桁の文字列にフォーマットする。null/undefined は '—' を返す。
 * @param {number|null|undefined} n
 * @returns {string}
 */
function fmt1(n) {
  return n != null && isFinite(n) ? n.toFixed(1) : '—';
}

/**
 * PER/PEG 生値表示（小数点1桁）。
 * @param {number|null|undefined} n
 * @returns {string}
 */
function fmtRaw(n) {
  return n != null && isFinite(n) ? n.toFixed(1) : '—';
}

/**
 * バーディクトから chip の CSS クラス名を返す。罠は2種を区別する。
 * @param {import('./valuations.js').Verdict} verdict
 * @returns {string}
 */
function chipClass(verdict) {
  if (verdict.class === 'trap') {
    return verdict.sub === 'trap_once' ? 'val-chip vc-trap-once' : 'val-chip vc-trap-cheap';
  }
  return `val-chip vc-${escapeHTML(verdict.class)}`;
}

/**
 * 確信度コードを日本語ラベルに変換する。
 * @param {'probe'|'standard'|'high'|null} conviction
 * @returns {string}
 */
function convictionLabel(conviction) {
  if (conviction === 'probe') return '打診';
  if (conviction === 'standard') return '標準';
  if (conviction === 'high') return '高確信';
  return '';
}

/**
 * サイズバー HTML を生成する（左端=0%・右端=適正×2・適正は常に中央）。
 * 塗りが中央を超える＝持ちすぎ、届かない＝持たなすぎ。
 * 適正の2倍超は塗りを満タンにし右端に倍率「× N」を表示。
 * 適正マーカー（▲）直下に「適正%（確信度）」を1行で示す。
 * @param {number} currentPct
 * @param {number|null} targetPct
 * @param {'probe'|'standard'|'high'|null} conviction
 * @returns {string}
 */
function sizeBarHTML(currentPct, targetPct, conviction) {
  if (targetPct == null || !isFinite(targetPct) || targetPct <= 0) {
    return `<div class="val-sb val-sb--na">
      <div class="val-sb-top"></div>
      <div class="val-sb-bar"></div>
      <div class="val-sb-scale"><span class="end"></span><span class="mid"><span class="lab">適正—</span></span><span class="end"></span></div>
    </div>`;
  }
  const scaleMax = targetPct * 2; // 右端 = 適正の2倍
  const ratio = currentPct / scaleMax; // 1.0 で中央=適正、0.5で左1/4…
  const fillW = Math.min(100, Math.max(0, ratio * 100));
  const diff = currentPct - targetPct;
  const fillCls = diff > 0.5 ? 'over' : diff < -0.5 ? 'under' : 'fit';
  const curLeft = Math.min(94, Math.max(6, fillW)); // tip ラベルの見切れ防止
  const overflow = currentPct > scaleMax;
  const mult = overflow ? currentPct / targetPct : null;
  const xnum = overflow && mult != null ? `<span class="val-sb-x">× ${mult.toFixed(1)}</span>` : '';
  const convTxt = convictionLabel(conviction);
  const convHTML = convTxt ? `<span class="cv">（${escapeHTML(convTxt)}）</span>` : '';
  return `<div class="val-sb">
    <div class="val-sb-top"><span class="val-sb-cur ${fillCls}" style="left:${curLeft.toFixed(0)}%">${fmt1(currentPct)}%</span></div>
    <div class="val-sb-bar"><span class="val-sb-fill ${fillCls}" style="width:${fillW.toFixed(1)}%"></span>${xnum}</div>
    <div class="val-sb-scale">
      <span class="end">持たなすぎ</span>
      <span class="mid"><span class="tri" aria-hidden="true"></span><span class="lab">${fmt1(targetPct)}%${convHTML}</span></span>
      <span class="end">持ちすぎ</span>
    </div>
  </div>`;
}

/**
 * 用語チップ（ⓘタップでその場に解説アコーディオンを開く・#475）。
 * glossary に解説があれば native details（ⓘ付き）、無ければプレーン表示（ⓘ無し）にフォールバック。
 * valueHTML は呼び出し側が組む（色クラス付き span を許容＝アプリ内由来の値のみ）。プレーン文字列は
 * 呼び出し側で escapeHTML 済みを渡すこと。
 * @param {string} cls   ルート class（'val-card' | 'val-c' | 'val-stat'）
 * @param {string} title ラベル
 * @param {string} valueHTML 数値部の HTML
 * @param {string} key   glossary キー
 * @param {string} [extraSummaryCls] summary 追加 class（is-sortkey 等）
 * @returns {string}
 */
function termChip(cls, title, valueHTML, key, extraSummaryCls = '') {
  const t = glossaryTermByKey(key);
  const sCls = extraSummaryCls ? ` ${extraSummaryCls}` : '';
  if (!t) {
    // 解説なし → details にせずプレーン（壊れたⓘを出さない）
    return `<div class="${cls}${sCls}"><span class="t">${escapeHTML(title)}</span><span class="v">${valueHTML}</span></div>`;
  }
  return `<details class="${cls}">
    <summary class="${cls}-h${sCls}" aria-label="${escapeHTML(title)} の説明を開く"><span class="t">${escapeHTML(title)}</span><span class="v">${valueHTML}</span><span class="ti" aria-hidden="true">ⓘ</span></summary>
    <p class="${cls}-x">${escapeHTML(t.desc)}</p>
  </details>`;
}

/**
 * レンズの並べ替え基準を、コア4チップ（PER/%タイル/品質/モメンタム）の強調位置に1対1で対応づける
 * （純関数・テスト対象・#504 F）。サイズ乖離レンズはチップ無しでサイズバーをリング強調。
 * @param {string} lens
 * @returns {{ chip: 'pct'|'qual'|'mom'|null, sizeBar: boolean }}
 */
export function sortKeyForLens(lens) {
  switch (lens) {
    case 'total':
      return { chip: null, sizeBar: true }; // gap DESC → サイズバー強調
    case 'value':
      return { chip: 'pct', sizeBar: false }; // percentile ASC → %タイルチップ
    case 'quality':
      return { chip: 'qual', sizeBar: false }; // qScore DESC → 品質チップ
    case 'momentum':
      return { chip: 'mom', sizeBar: false }; // priceMom1Y DESC → モメンタムチップ
    default:
      return { chip: null, sizeBar: false };
  }
}

/**
 * 固定コアチップ（PER／%タイル／品質／モメンタム の4枚・2×2・#504 F）。レンズに応じて
 * 対応チップ（value→%タイル/quality→品質/momentum→モメンタム）に is-sortkey を付与する。
 * 全レンズ同一構成（作り替えない）。PEG/EV-EBITDA・Fスコア等は詳細①②に既出。
 * @param {any|null} val
 * @param {string} lens
 * @returns {string}
 */
function coreChipsHTML(val, lens) {
  const v = (val && val.value) || {};
  const q = (val && val.quality) || {};
  const mo = (val && val.momentum) || {};
  const sk = sortKeyForLens(lens);
  const per = `${fmtRaw(v.perTrail)}→${fmtRaw(v.perFwd)}`;
  const pct = val && val.percentile != null && isFinite(val.percentile) ? `${Math.round(val.percentile)}%ile` : '—';
  const qual = q.qScore != null && isFinite(q.qScore) ? `Q${Math.round(q.qScore)}` : '—';
  const mom =
    mo.priceMom1Y != null && isFinite(mo.priceMom1Y)
      ? `${mo.priceMom1Y >= 0 ? '+' : ''}${Math.round(mo.priceMom1Y)}%`
      : '—';
  // 各チップ = ⓘ付き termChip。ソートキー強調 is-sortkey は位置 id（per/pct/qual/mom）で付与・維持。
  const skCls = (posId) => (sk.chip === posId ? 'is-sortkey' : '');
  return `<div class="val-chips">
    ${termChip('val-c', 'PER', escapeHTML(per), 'per', skCls('per'))}
    ${termChip('val-c', '%タイル', escapeHTML(pct), 'percentile', skCls('pct'))}
    ${termChip('val-c', '品質', escapeHTML(qual), 'qScore', skCls('qual'))}
    ${termChip('val-c', 'モメンタム', escapeHTML(mom), 'priceMom1Y', skCls('mom'))}
  </div>`;
}

/**
 * 1指標=1行の「目安ゲージ行」（#475 rev2）。ラベル＋ⓘ＋数値＋判定バッジ＋目安バー
 * （goodゾーン/目安tick/現在地マーカー/同業破線=将来）＋目安キャプション。タップで解説展開。
 * メタ＆閾値は value-detail-meta.js が正本。データ欠損の指標は行ごと出さない。
 * @param {import('./value-detail-meta.js').MetricMeta} meta
 * @param {any} val
 * @returns {string}
 */
function detailRow(meta, val) {
  const m = computeMetric(meta, val);
  if (m == null) return ''; // データ無し→行を出さない（空 gauge を出さない）
  const t = glossaryTermByKey(meta.key);
  // 中立（neu）は判定バッジを出さない（「・ 文脈次第」を撲滅・#504 B）。マーカー色は neu のままでよい。
  const badge =
    m.judge && m.tone !== 'neu'
      ? `<span class="vg-badge vg-${m.tone}">${m.judge.glyph} ${escapeHTML(m.judge.label)}</span>`
      : '';
  const tag = meta.live ? `<span class="vg-live">${escapeHTML(meta.liveTag || '')}</span>` : '';
  // 同業中央値の破線ラベル。質を正直に: 米株 peer 群=「同業 n=N」/ JP ETF proxy=「同業(proxy)」（#493/#497）
  const peerLab =
    m.peer != null
      ? `<span class="vg-peer-lab">${m.peerSource === 'etf-proxy' ? '同業(proxy)' : `同業 n=${m.peerN != null ? m.peerN : '—'}`}</span>`
      : '';
  // ⓘ展開＝この銘柄ならではの評価（evalText）＋用語解説への誘導（#504 B）。
  // 一般的な定義は glossary が正本＝vg-expl に generic desc を二度書きしない。
  const ev = meta.evalText ? meta.evalText(val) : null;
  const glossLink = '<a class="vg-gloss-link" href="#val-glossary">用語の意味を見る →</a>';
  const iGlyph = ev || t ? `<span class="vg-i" aria-hidden="true">ⓘ</span>` : '';
  const expl = ev
    ? `<p class="vg-expl">この銘柄: ${escapeHTML(ev)} ${glossLink}</p>`
    : t
      ? `<p class="vg-expl vg-expl--link">意味は<a class="vg-gloss-link" href="#val-glossary">用語解説</a>へ</p>`
      : '';
  // gauge 内訳（全て clamp 済み・% 配置）
  const z0 = m.zone ? Math.min(m.zone[0], m.zone[1]) : 0;
  const zw = m.zone ? Math.abs(m.zone[1] - m.zone[0]) : 0;
  const zoneHTML = m.zone
    ? `<span class="vg-zone vg-${m.tone}" style="left:${z0.toFixed(0)}%;width:${zw.toFixed(0)}%"></span>`
    : '';
  const tickHTML = m.tick != null ? `<span class="vg-tick" style="left:${m.tick.toFixed(0)}%"></span>` : '';
  const peerHTML = m.peer != null ? `<span class="vg-peer" style="left:${m.peer.toFixed(0)}%"></span>` : ''; // 将来（同業中央値）
  const mkHTML = `<span class="vg-mk vg-${m.tone}" style="left:${m.pos.toFixed(0)}%"></span>`;
  return `<details class="vg-row">
    <summary aria-label="${escapeHTML(meta.label)} の説明を開く">
      <span class="vg-top"><span class="vg-lab">${escapeHTML(meta.label)}</span>${iGlyph}<span class="vg-right"><span class="vg-val">${m.valueHTML}</span>${badge}</span></span>
      <span class="vg-gauge">${zoneHTML}${tickHTML}${peerHTML}${mkHTML}</span>
      <span class="vg-ends"><span>割安 / 低</span><span>割高 / 高</span></span>
      <span class="vg-bot">${tag}${peerLab}<span class="vg-cap">${escapeHTML(meta.cap)}</span></span>
    </summary>
    ${expl}
  </details>`;
}

/**
 * 「詳細指標」タップ展開（全レンズ同一内容）。コア4は重複回避で載せない。
 * 3つの問い（割安か/稼ぐか/期待勢い）でグルーピングし、各指標を目安ゲージ行で出す。
 * @param {any|null} val
 * @returns {string}
 */
function detailHTML(val) {
  if (!val) return '';
  const groupHTML = (g) => {
    const rows = VALUE_DETAIL_META.filter((meta) => meta.group === g)
      .map((meta) => detailRow(meta, val))
      .join('');
    if (!rows) return '';
    const gi = VALUE_DETAIL_GROUPS[g];
    // 文字のみ見出し（番号は本文色・下罫線だけ・カード/帯にしない・#504 C）
    return `<div class="val-detail-grp"><div class="grp-h"><span class="lab">${escapeHTML(gi.label)}</span><span class="grp-cap">${escapeHTML(gi.cap)}</span></div><div class="vg-rows">${rows}</div></div>`;
  };
  const body = [1, 2, 3].map(groupHTML).join('');
  if (!body) return '';
  // 目安バーの見方（凡例）を詳細先頭に1回だけ（各行には出さない・#504 D）
  const legend = `<div class="vg-legend">
    <div class="vg-legend-ttl">目安バーの見方</div>
    <div class="vg-legend-bar"><span class="vg-zone vg-good" style="left:8%;width:46%"></span><span class="vg-tick" style="left:50%"></span><span class="vg-peer" style="left:72%"></span><span class="vg-mk vg-good" style="left:34%"></span></div>
    <ul class="vg-legend-items">
      <li><span class="lg-sw lg-zone"></span>良い範囲（目安）</li>
      <li><span class="lg-sw lg-mk"></span>いまの値（この銘柄）</li>
      <li><span class="lg-sw lg-tick"></span>目安ライン（中央値/しきい値）</li>
      <li><span class="lg-sw lg-peer"></span>同業中央値（破線）</li>
    </ul>
  </div>`;
  // アコーディオン行（背景＋枠＋SVGシェブロン・#512）。native details のまま JS 不要。
  const summary = `<summary class="val-detail-tog">
    <span class="vdt-lab">詳細指標</span>
    <span class="vdt-sub">13指標・目安バー・同業比較</span>
    <svg class="vdt-chev" viewBox="0 0 24 24" aria-hidden="true"><polyline points="6 9 12 15 18 9"></polyline></svg>
  </summary>`;
  return `<details class="val-detail">${summary}${legend}${body}</details>`;
}

/**
 * カード上部のアクションバナー HTML を生成する。
 * トリガーがあればその行動（トリム/積増/監視）、無ければ「維持」。
 * @param {{ active: Array<{side:string,type:string,action:string,reason:string}>, watching: Array<{side:string,type:string,action:string,note:string}> }|null} trig
 * @returns {string}
 */
function bannerHTML(trig) {
  let kind = 'hold';
  let icon = 'vb-hold';
  let action = '維持';
  let reason = '';
  if (trig && trig.active.length > 0) {
    const t = trig.active[0];
    if (t.side === 'sell') {
      kind = 'sell';
      icon = 'vb-trim';
      action = 'トリム';
    } else {
      kind = 'buy';
      icon = 'vb-add';
      action = '積増';
    }
    reason = t.reason || t.action || '';
  } else if (trig && trig.watching.length > 0) {
    const w = trig.watching[0];
    kind = 'watch';
    icon = 'vb-watch';
    action = '監視';
    reason = w.note || w.action || '';
  }
  const reasonHTML = reason ? `<span class="vb">${escapeHTML(reason)}</span>` : '';
  // 記号 ▼▲◦▪ 廃止 → SVG ラインアイコン（同一文書 use・外部参照なし＝CSP 安全・#504 G）
  return `<div class="val-banner val-banner--${kind}"><span class="va"><svg class="vb-ic" viewBox="0 0 24 24" aria-hidden="true"><use href="#${icon}"/></svg>${action}</span>${reasonHTML}</div>`;
}

/**
 * アクションバナー用 SVG スプライト（feather 風・stroke=currentColor）。renderValuationTab の
 * 出力先頭に1回だけ置く。各バナーは <use href="#vb-*"> で参照（CSP 安全）。
 * @type {string}
 */
const VAL_BANNER_SPRITE =
  '<svg class="val-sprite" aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden">' +
  '<defs>' +
  '<g id="vb-add" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 17 9 11 13 15 21 7"/><polyline points="15 7 21 7 21 13"/></g>' +
  '<g id="vb-trim" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 7 9 13 13 9 21 17"/><polyline points="15 17 21 17 21 11"/></g>' +
  '<g id="vb-watch" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M1.5 12S5 5.5 12 5.5 22.5 12 22.5 12 19 18.5 12 18.5 1.5 12 1.5 12Z"/><circle cx="12" cy="12" r="3"/></g>' +
  '<g id="vb-hold" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6.5 9.5 17 4.5 12"/></g>' +
  '</defs></svg>';

/**
 * カード下部の判定確度 行 HTML を生成する（confidence が無ければ空文字）。
 * @param {import('./valuations.js').Verdict|null} verdict
 * @returns {string}
 */
function confidenceHTML(verdict) {
  if (!verdict || verdict.confidence == null) return '';
  const lv = verdict.confidence;
  const dots = lv === '高' ? 3 : lv === '中' ? 2 : 1;
  let dotsHTML = '';
  for (let i = 0; i < 3; i++) dotsHTML += `<i class="d${i < dots ? ' on' : ''}"></i>`;
  const drv =
    verdict.drivers && verdict.drivers.length
      ? `<span class="drv">根拠: ${escapeHTML(verdict.drivers.join('・'))}</span>`
      : '';
  return `<div class="val-jc"><span class="jc-nm">判定確度</span><span class="jc-dots" aria-label="判定確度 ${escapeHTML(lv)}">${dotsHTML}<span class="lv">${escapeHTML(lv)}</span></span>${drv}</div>`;
}

/**
 * 1 銘柄分のカード HTML を生成する。
 * 構成: アクションバナー → シンボル+verdict → サイズバー → コアチップ → 判定確度 → 詳細指標。
 * @param {{ symbol:string, name:string, value:number, ySymbol:string, cat:string, cur:string, proxyName?:string, isProxy?:boolean }} p
 * @param {number} currentPct
 * @param {number|null} targetPct
 * @param {import('./valuations.js').Verdict|null} verdict
 * @param {any|null} val
 * @param {{ active: Array<any>, watching: Array<any> }|null} trig
 * @param {'probe'|'standard'|'high'|null} conviction
 * @returns {string}
 */
function rowHTML(p, currentPct, targetPct, verdict, val, trig, conviction) {
  // アクションバナー（全レンズ共通・常時表示）
  const banner = bannerHTML(trig);

  // 上段: シンボル + 銘柄名（下揃え）+ verdict chip + proxy バッジ
  const chipHTML =
    verdict && verdict.label && verdict.label !== '-'
      ? `<span class="${chipClass(verdict)}" title="${escapeHTML(verdict.drivers.join('・'))}">${escapeHTML(verdict.label)}</span>`
      : '';
  // proxy ETF（value.perSource:"fund-trailing"）は判定が proxy 由来である旨をバッジ表示。
  // 代替指数名を明記して「ファンド本体の割安/割高」と誤読されないようにする（#529）。
  const isProxy = !!(val && val.value && val.value.perSource === 'fund-trailing');
  const proxyShort = PROXY_LABELS[p.ySymbol] || p.proxyName || p.ySymbol || '指数';
  const proxyTitle = `${p.proxyName || proxyShort} の実績PER（プロキシ指数）。${p.name}本体の数値ではありません。`;
  const proxyHTML = isProxy
    ? `<span class="val-proxy" title="${escapeHTML(proxyTitle)}">proxy: ${escapeHTML(proxyShort)}</span>`
    : '';
  // 見出しを共通 .card-ttl（アイコン箱）へ統一（#515 P2・Value にもアイコン追加=gauge）
  const head = `<div class="val-head card-ttl">
    <span class="tic"><svg class="ric" aria-hidden="true"><use href="#i-gauge"/></svg></span>
    <b class="val-tk">${escapeHTML(p.symbol)}</b>
    <span class="val-nm">${escapeHTML(p.name)}</span>
    ${chipHTML}${proxyHTML}
  </div>`;

  // サイズバー（全レンズ共通）。total レンズは並べ替えキー＝サイズ乖離なのでリング強調。
  const sk = sortKeyForLens(_lens);
  const size = `<div class="val-size-wrap${sk.sizeBar ? ' is-sortkey' : ''}">${sizeBarHTML(currentPct, targetPct, conviction)}</div>`;

  // 指標段。アクティブ投信の本体評価（fund-monthly-top10・#530）は value 系メトリクスを持たないため、
  // コアチップ/詳細の代わりに「本体PER＋月次上位10カバー率」を出す。coverage<0.5 / status:na は「参考」。
  const fm = val && val.source === 'fund-monthly-top10' ? val : null;
  let metricsBlock;
  if (fm) {
    const cov = typeof fm.coverage === 'number' ? Math.round(fm.coverage * 100) : null;
    const ref = (typeof fm.coverage === 'number' && fm.coverage < 0.5) || fm.status === 'na';
    metricsBlock = `<div class="val-fundmo">
      <div class="val-fundmo-top"><span class="t">PER（本体）</span><span class="v">${escapeHTML(fmtRaw(fm.perCurrent))}</span>${ref ? '<span class="val-fundmo-ref">参考</span>' : ''}</div>
      <div class="val-fundmo-lab">月次上位10ベース（カバー率${cov != null ? cov + '%' : '—'}・${escapeHTML(fm.asOf || '—')}）</div>
    </div>`;
  } else {
    // 通常: 固定コアチップ4枚＋判定確度＋詳細展開（作り替えない）
    metricsBlock = `${coreChipsHTML(val, _lens)}${confidenceHTML(verdict)}${detailHTML(val)}`;
  }

  // 並び: banner → head → size → (fund-monthly: 本体PER / 通常: チップ＋確度＋詳細)
  return `<div class="val-row">${banner}<div class="val-body">${head}${size}${metricsBlock}</div></div>`;
}

/**
 * 現在の _lens に応じて rows を並び替えて返す（元配列は変更しない）。
 * @param {Array<{p:any,currentPct:number,targetPct:number|null,gap:number|null,verdict:any,val:any,trig:any,conviction?:any}>} rows
 * @returns {Array<{p:any,currentPct:number,targetPct:number|null,gap:number|null,verdict:any,val:any,trig:any,conviction?:any}>}
 */
function sortedRows(rows) {
  const copy = rows.slice();
  if (_lens === 'total') {
    // gap DESC (null は最後)
    copy.sort((a, b) => {
      if (a.gap == null && b.gap == null) return 0;
      if (a.gap == null) return 1;
      if (b.gap == null) return -1;
      return b.gap - a.gap;
    });
  } else if (_lens === 'value') {
    // percentile ASC (cheap first; null last)
    copy.sort((a, b) => {
      const pa = a.val && a.val.percentile != null && isFinite(a.val.percentile) ? a.val.percentile : null;
      const pb = b.val && b.val.percentile != null && isFinite(b.val.percentile) ? b.val.percentile : null;
      if (pa == null && pb == null) return 0;
      if (pa == null) return 1;
      if (pb == null) return -1;
      return pa - pb;
    });
  } else if (_lens === 'quality') {
    // qScore DESC (null last)
    copy.sort((a, b) => {
      const qa =
        a.val && a.val.quality && a.val.quality.qScore != null && isFinite(a.val.quality.qScore)
          ? a.val.quality.qScore
          : null;
      const qb =
        b.val && b.val.quality && b.val.quality.qScore != null && isFinite(b.val.quality.qScore)
          ? b.val.quality.qScore
          : null;
      if (qa == null && qb == null) return 0;
      if (qa == null) return 1;
      if (qb == null) return -1;
      return qb - qa;
    });
  } else if (_lens === 'momentum') {
    // priceMom1Y DESC (null last)
    copy.sort((a, b) => {
      const ma =
        a.val && a.val.momentum && a.val.momentum.priceMom1Y != null && isFinite(a.val.momentum.priceMom1Y)
          ? a.val.momentum.priceMom1Y
          : null;
      const mb =
        b.val && b.val.momentum && b.val.momentum.priceMom1Y != null && isFinite(b.val.momentum.priceMom1Y)
          ? b.val.momentum.priceMom1Y
          : null;
      if (ma == null && mb == null) return 0;
      if (ma == null) return 1;
      if (mb == null) return -1;
      return mb - ma;
    });
  }
  return copy;
}

/**
 * レンズごとのキャプション文字列を返す。
 * @param {string} lens
 * @returns {string}
 */
function lensCap(lens) {
  if (lens === 'total') return '乖離順｜サイズ過大が上';
  if (lens === 'value') return '%タイル昇順｜割安が上';
  if (lens === 'quality') return 'qScore順｜ROIC<WACCは赤・Altman Z<3は注意色';
  if (lens === 'momentum') return '1Y騰落順';
  return '';
}

/**
 * Value タブを描画する。_lens に応じてソート・メトリクスを切り替える。
 * @returns {Promise<void>}
 */
export async function renderValuationTab() {
  const wrap = document.getElementById('value-wrap');
  if (!wrap) return;

  // データ読み込み
  await _ensureData();

  // 分母（総評価額 JPY）
  const totals = getMfTotals();
  const denom = (totals && totals.imported) || positions.reduce((s, p) => s + (p.value || 0), 0);

  if (denom <= 0 || positions.length === 0) {
    wrap.innerHTML = '<div class="val-soon">データ準備中。マネフォ取込またはCSV取込を実行してください。</div>';
    return;
  }

  // 価格モメンタムを履歴キャッシュ（1y close 系列）から自動算出。
  // valuations.json の手動シードが優先、null の項目だけ live 値で埋める。
  // getAllHistorical は内部で例外を握り潰し {} を返すため try/catch 不要。
  const _hist = /** @type {Record<string, Array<{date: Date, close: number}>>} */ (await getAllHistorical('1y'));
  // 対市場の相対強さ（rsVsSector）のベンチ＝世界株 ACWI（保有・履歴キャッシュにある）。
  const _benchSeries = _hist['ACWI'] || null;

  // symbol → currentPct マップ（テーマ使用率計算用）
  /** @type {Record<string, number>} */
  const currentPctBySymbol = {};
  for (const p of positions) {
    const pct = ((p.value || 0) / denom) * 100;
    // ySymbol と symbol 両方にマップ（computeThemeUsage は members で参照するため）
    if (p.ySymbol) currentPctBySymbol[p.ySymbol] = pct;
    if (p.symbol && p.symbol !== p.ySymbol) currentPctBySymbol[p.symbol] = pct;
  }

  // 各銘柄のメトリクスを計算
  /** @type {Array<{p: any, currentPct: number, targetPct: number|null, gap: number|null, verdict: import('./valuations.js').Verdict|null, val: any|null, tkey: string|null, trig: {active:Array<any>,watching:Array<any>}|null, conviction: 'probe'|'standard'|'high'|null}>} */
  const rows = positions.map((p) => {
    const currentPct = ((p.value || 0) / denom) * 100;

    // target key を解決: ySymbol → symbol → name の優先順で最初に結果が得られるものを使う
    /** @type {string|null} */
    let tkey = null;
    for (const candidate of [p.ySymbol, p.symbol, p.name]) {
      if (!candidate) continue;
      if (getTargetPct(candidate) != null || getThemeOf(candidate) != null) {
        tkey = candidate;
        break;
      }
    }

    const targetPct = tkey != null ? getTargetPct(tkey) : null;
    const gap = targetPct != null ? currentPct - targetPct : null;
    const conviction = tkey != null ? getConviction(tkey) : null;

    // アクティブ投信は本体の「月次上位10加重PER」（canonicalName=p.name でキー）を proxy より優先（#530）。
    // 無ければ従来どおり proxy ETF（p.ySymbol）。fund-monthly は percentile を持たないので
    // computeVerdict は自動的に na（強い割安/割高を断定しない）＝coverage<0.5 でも安全。
    const fundMonthly = getValuation(p.name);
    const useFundMonthly = !!(fundMonthly && fundMonthly.source === 'fund-monthly-top10');
    let val = useFundMonthly ? fundMonthly : getValuation(p.ySymbol);
    // 価格モメンタム（priceMom1Y / pos52w / rsVsSector=対ACWI）を履歴から live 補完（null のみ）。
    // fund-monthly はファンド本体評価なので proxy 価格由来のモメンタムは載せない。
    const liveMom = p.ySymbol ? computePriceMomentum(_hist[p.ySymbol]) : null;
    const liveRs = p.ySymbol && _benchSeries ? relStrength(_hist[p.ySymbol], _benchSeries) : null;
    if (!useFundMonthly && (liveMom || liveRs != null)) {
      const m = (val && val.momentum) || {};
      val = {
        ...(val || {}),
        momentum: {
          ...m,
          priceMom1Y: m.priceMom1Y != null ? m.priceMom1Y : liveMom ? liveMom.priceMom1Y : null,
          pos52w: m.pos52w != null ? m.pos52w : liveMom ? liveMom.pos52w : null,
          rsVsSector: m.rsVsSector != null ? m.rsVsSector : liveRs,
        },
      };
    }
    const verdict = val ? computeVerdict(val) : null;

    // テーマ使用率（concentration トリガー用）
    const trigTheme = (tkey && getThemeOf(tkey)) || (p.ySymbol && getThemeOf(p.ySymbol)) || null;
    const themeUsagePct = trigTheme ? computeThemeUsage(trigTheme, currentPctBySymbol).used : null;

    // proxy ETF 判定（value.perSource:"fund-trailing" が立っている＝自前PERが proxy）
    const isEtf = !!(val && val.value && val.value.perSource === 'fund-trailing');

    // トリガーを評価（ySymbol 優先、次に symbol）
    const trigSymbol = getTriggers(p.ySymbol) ? p.ySymbol : getTriggers(p.symbol) ? p.symbol : null;
    const trig = trigSymbol
      ? evaluateTriggers(trigSymbol, {
          percentile: val && val.percentile != null ? val.percentile : null,
          peg: val && val.value && val.value.peg != null ? val.value.peg : null,
          themeUsagePct,
          price: p.price != null ? p.price : null,
          isEtf,
        })
      : null;

    return { p, currentPct, targetPct, gap, verdict, val, tkey, trig, conviction };
  });

  // ヘッダー統計（常に総合ベースで計算）
  const overCount = rows.filter((r) => r.gap != null && r.gap > 0.5).length;
  const cheapCount = rows.filter((r) => r.verdict && r.verdict.class === 'cheap_real').length;
  const triggerCount = rows.filter((r) => r.trig && r.trig.active.length > 0).length;
  const watchCount = rows.filter((r) => r.trig && r.trig.watching.length > 0).length;

  // D-4 / #450: 的中率を 発議(action) / 判定(verdict) 別に hits/resolved 表記で表示する。
  // `-` の引き算誤読を避け、未判定は「判定待ちN」で集計中を明示。率が高いと軽い accent。
  const hrA = computeHitRate('action');
  const hrV = computeHitRate('verdict');
  const hrPart = (label, hr) => {
    if (hr.resolved > 0) {
      const hot = hr.ratePct != null && hr.ratePct >= 60 ? ' hr-hot' : '';
      return `<span class="hr-p${hot}" title="${label}的中率 ${hr.ratePct}%（hits/判定済・対ACWI相対）" aria-label="${label} ${hr.hits}当たり ${hr.resolved}件中">${label} ${hr.hits}/${hr.resolved}</span>`;
    }
    if (hr.pending > 0) return `<span class="hr-p">${label} 判定待ち${hr.pending}</span>`;
    return `<span class="hr-p">${label}—</span>`;
  };
  // 的中率＝発議/判定 を2段（キリよく改行・#504 A）
  const hitRateVal = `${hrPart('発議', hrA)}<span class="l2">${hrPart('判定', hrV)}</span>`;
  // トリガー: active=抵触 / watching=監視 を2段（抵触＝アクションバナー化する銘柄数・#504 A）
  const trigVal = `<span class="hr-p">抵触 ${triggerCount}</span><span class="l2"><span class="hr-p">監視 ${watchCount}</span></span>`;
  // 各統計に個別ⓘ（termChip）。旧「ⓘ 統計の見方」単独 details は撤去し各統計へ集約（#475）。
  const statsHTML = `<div class="val-stats">
    ${termChip('val-stat', '過大ポジ', escapeHTML(String(overCount)), 'overweightCount')}
    ${termChip('val-stat', '割安候補', escapeHTML(String(cheapCount)), 'cheapCount')}
    ${termChip('val-stat', '的中率', hitRateVal, 'hitRate')}
    ${termChip('val-stat', 'トリガー', trigVal, 'sellTriggers')}
  </div>`;

  // レンズ切替ピル（4つすべて有効）
  const lenses = [
    { key: 'total', label: 'サイズ乖離' },
    { key: 'value', label: 'バリュ' },
    { key: 'quality', label: '品質' },
    { key: 'momentum', label: 'モメンタム' },
  ];
  const pillsHTML = lenses
    .map(
      (l) =>
        `<button class="val-seg${_lens === l.key ? ' on' : ''}" role="tab" aria-selected="${_lens === l.key}" data-lens="${escapeHTML(l.key)}">${escapeHTML(l.label)}</button>`
    )
    .join('');
  const lensHTML = `<div class="val-lens" role="tablist" aria-label="レンズ選択">${pillsHTML}</div>
  <div class="val-lens-cap">${escapeHTML(lensCap(_lens))}</div>`;

  // 現在レンズでソートして行を生成
  const sorted = sortedRows(rows);
  const rowsHTML = sorted
    .map((r) => rowHTML(r.p, r.currentPct, r.targetPct, r.verdict, r.val, r.trig, r.conviction))
    .join('');

  wrap.innerHTML = `${VAL_BANNER_SPRITE}${statsHTML}${lensHTML}<div class="val-list">${rowsHTML}</div><div id="val-glossary">${glossaryHTML('value')}</div>`;

  // ピルのクリックで _lens を更新して再描画（CSP 安全な addEventListener）
  wrap.querySelectorAll('.val-seg[data-lens]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const nextLens = /** @type {HTMLElement} */ (btn).dataset.lens;
      if (!nextLens || nextLens === _lens) return;
      _lens = nextLens;
      renderValuationTab();
    });
  });
}
